-- Additive SPLIT_V1 Core upgrade. Apply only with the matching verified release.
-- Generated from separation/snapshot-revisions.js; no learning records are rewritten.
-- The final marker enables snapshots only after all triggers are installed.
CREATE TRIGGER IF NOT EXISTS academy_snapshot_activities_insert AFTER INSERT ON "activities" BEGIN INSERT INTO academy_settings(setting_key,setting_value,updated_at,updated_by_account_id) VALUES('AcademySnapshot:audience:'||'GLOBAL','1',strftime('%Y-%m-%dT%H:%M:%fZ','now'),NULL) ON CONFLICT(setting_key) DO UPDATE SET setting_value=CAST(setting_value AS INTEGER)+1,updated_at=excluded.updated_at; END;
CREATE TRIGGER IF NOT EXISTS academy_snapshot_activities_update AFTER UPDATE OF active,lifecycle,website_visible ON "activities" WHEN (OLD.active IS NOT NEW.active OR OLD.lifecycle IS NOT NEW.lifecycle OR OLD.website_visible IS NOT NEW.website_visible) BEGIN INSERT INTO academy_settings(setting_key,setting_value,updated_at,updated_by_account_id) VALUES('AcademySnapshot:audience:'||'GLOBAL','1',strftime('%Y-%m-%dT%H:%M:%fZ','now'),NULL) ON CONFLICT(setting_key) DO UPDATE SET setting_value=CAST(setting_value AS INTEGER)+1,updated_at=excluded.updated_at; END;
